// Server-rendered HTML of aphrody.app (landing, labs, dashboard). Material 3: color roles from the brand seed
// (`--md-sys-color-*`, generated by m3.ts), M3 type scale, shape and state layers; components follow the M3
// specs (top app bar, outlined and filled cards, lists, filled and tonal buttons, assist chips). No JavaScript.
import {
  previewUrl,
  type Deployment,
  type LabCard,
  type Project,
  type ProjectState,
  type Registry,
} from "./state.ts";

export const esc = (s: unknown): string =>
  String(s ?? "").replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ]!,
  );

const BASE_CSS = `
:root{color-scheme:light dark;--md-ref-typeface-brand:"Google Sans Flex","Roboto Flex",system-ui,sans-serif;--md-ref-typeface-plain:"Roboto Flex",system-ui,sans-serif;--md-sys-shape-corner-medium:12px;--md-sys-shape-corner-large:16px;--md-sys-shape-corner-full:9999px}
*{box-sizing:border-box}
body{margin:0;background:var(--md-sys-color-surface);color:var(--md-sys-color-on-surface);font:400 1rem/1.5rem var(--md-ref-typeface-plain);letter-spacing:.03125rem}
a{color:var(--md-sys-color-primary)}
a:focus-visible,button:focus-visible{outline:3px solid var(--md-sys-color-secondary);outline-offset:2px}
.top-app-bar{display:flex;align-items:center;gap:16px;height:64px;padding:0 16px;background:var(--md-sys-color-surface-container);position:sticky;top:0}
.top-app-bar .brand{display:flex;align-items:center;gap:12px;color:var(--md-sys-color-on-surface);text-decoration:none;font:500 1.375rem/1.75rem var(--md-ref-typeface-brand)}
.top-app-bar .brand svg{width:32px;height:32px}
.top-app-bar nav{margin-left:auto;display:flex;gap:4px}
.top-app-bar nav a{display:inline-flex;align-items:center;min-height:40px;padding:0 12px;border-radius:var(--md-sys-shape-corner-full);color:var(--md-sys-color-on-surface-variant);text-decoration:none;font:500 .875rem/1.25rem var(--md-ref-typeface-plain);letter-spacing:.00625rem}
.top-app-bar nav a[aria-current=page]{background:var(--md-sys-color-secondary-container);color:var(--md-sys-color-on-secondary-container)}
main{max-width:1200px;margin:0 auto;padding:24px 16px 64px}
.display-small{font:400 2.25rem/2.75rem var(--md-ref-typeface-brand);margin:32px 0 8px}
.headline-small{font:400 1.5rem/2rem var(--md-ref-typeface-brand);margin:40px 0 16px}
.title-medium{font:500 1rem/1.5rem var(--md-ref-typeface-plain);letter-spacing:.009375rem;margin:0}
.body-medium{font:400 .875rem/1.25rem var(--md-ref-typeface-plain);letter-spacing:.015625rem;color:var(--md-sys-color-on-surface-variant);margin:4px 0 0}
.label-medium{font:500 .75rem/1rem var(--md-ref-typeface-plain);letter-spacing:.03125rem}
.lead{max-width:60ch;color:var(--md-sys-color-on-surface-variant)}
.grid{display:grid;gap:16px;grid-template-columns:repeat(auto-fill,minmax(280px,1fr))}
.card-outlined{border:1px solid var(--md-sys-color-outline-variant);border-radius:var(--md-sys-shape-corner-medium);background:var(--md-sys-color-surface);padding:16px;display:flex;flex-direction:column;gap:8px}
.card-filled{border-radius:var(--md-sys-shape-corner-medium);background:var(--md-sys-color-surface-container-highest);padding:16px}
.card-outlined a.title-medium{color:var(--md-sys-color-on-surface);text-decoration:none}
.card-outlined a.title-medium:hover{text-decoration:underline}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:auto;padding-top:8px}
.chip{display:inline-flex;align-items:center;height:32px;padding:0 12px;border:1px solid var(--md-sys-color-outline-variant);border-radius:8px;color:var(--md-sys-color-on-surface-variant)}
.chip.ok{background:var(--md-sys-color-secondary-container);color:var(--md-sys-color-on-secondary-container);border-color:transparent}
.chip.err{background:var(--md-sys-color-error-container);color:var(--md-sys-color-on-error-container);border-color:transparent}
.list{list-style:none;margin:0;padding:8px 0;border-radius:var(--md-sys-shape-corner-medium);background:var(--md-sys-color-surface-container-low)}
.list li{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;min-height:56px;padding:8px 16px}
.list li+li{border-top:1px solid var(--md-sys-color-outline-variant)}
.list .grow{flex:1 1 240px;min-width:0}
code{font:400 .875rem/1.25rem ui-monospace,"Roboto Mono",monospace}
.btn-filled,.btn-tonal,.btn-text{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 24px;border:0;border-radius:var(--md-sys-shape-corner-full);font:500 .875rem/1.25rem var(--md-ref-typeface-plain);letter-spacing:.00625rem;text-decoration:none;cursor:pointer}
.btn-filled{background:var(--md-sys-color-primary);color:var(--md-sys-color-on-primary)}
.btn-tonal{background:var(--md-sys-color-secondary-container);color:var(--md-sys-color-on-secondary-container)}
.btn-text{background:none;color:var(--md-sys-color-primary);padding:0 12px}
.btn-filled:hover,.btn-tonal:hover,.btn-text:hover{box-shadow:inset 0 0 0 100vmax color-mix(in srgb,currentColor 8%,transparent)}
form{display:inline}
pre{white-space:pre-wrap;word-break:break-word;background:var(--md-sys-color-surface-container);padding:16px;border-radius:var(--md-sys-shape-corner-medium);font:400 .8125rem/1.25rem ui-monospace,"Roboto Mono",monospace}
footer{max-width:1200px;margin:0 auto;padding:24px 16px;color:var(--md-sys-color-on-surface-variant);border-top:1px solid var(--md-sys-color-outline-variant)}
@media (prefers-reduced-motion:no-preference){.btn-filled,.btn-tonal,.btn-text{transition:box-shadow .2s}}
`;

type Tab = "home" | "labs" | "dashboard";

export function layout(
  reg: Pick<Registry, "css" | "mark">,
  title: string,
  tab: Tab,
  body: string,
  desc = "",
): string {
  const nav = (t: Tab, href: string, label: string) =>
    `<a href="${href}"${t === tab ? ' aria-current="page"' : ""}>${label}</a>`;
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title>${desc ? `<meta name="description" content="${esc(desc)}">` : ""}<meta name="color-scheme" content="light dark"><link rel="canonical" href="https://aphrody.app${tab === "home" ? "/" : `/${tab}`}"><style>${reg.css}${BASE_CSS}</style></head><body><header class="top-app-bar"><a class="brand" href="/">${reg.mark}<span>aphrody.app</span></a><nav aria-label="Navigation">${nav("home", "/", "Projets")}${nav("labs", "/labs", "Labs")}${nav("dashboard", "/dashboard", "Tableau de bord")}</nav></header><main>${body}</main><footer class="body-medium">Aphrody. Code source : <a href="https://github.com/aphrody-labs/src">github.com/aphrody-labs/src</a>. Contact : <a href="mailto:contact@aphrody.com">contact@aphrody.com</a>. Holding : <a href="https://aphrody.com/">aphrody.com</a>.</footer></body></html>`;
}

const ago = (iso?: string) =>
  iso
    ? `<time datetime="${esc(iso)}">${esc(iso.slice(0, 16).replace("T", " "))} UTC</time>`
    : "jamais";

function prodUrl(p: Project): string {
  return p.domains[0] ? `https://${p.domains[0]}` : "";
}

export interface ProjectView {
  project: Project;
  state: ProjectState | null;
  latest: Deployment | null;
}

export function landing(reg: Registry, views: ProjectView[]): string {
  const cards = views
    .map(({ project: p, state: s, latest: d }) => {
      const url = prodUrl(p);
      return `<article class="card-outlined"><h3 class="title-medium">${esc(p.name)}</h3><p class="body-medium"><code>${esc(p.path)}</code></p>${url ? `<p class="body-medium">Production : <a href="${esc(url)}">${esc(p.domains[0])}</a>${s?.production ? ` (<code>${esc(s.production.slice(0, 7))}</code>)` : ""}</p>` : ""}${d ? `<p class="body-medium">Dernier déploiement : <a href="${esc(previewUrl(p.name, d.sha))}">${esc(d.sha.slice(0, 7))}</a>, ${ago(d.readyAt ?? d.createdAt)}</p>` : `<p class="body-medium">Aucun déploiement.</p>`}<div class="chips">${d ? `<span class="chip label-medium ${d.state === "ready" ? "ok" : d.state === "error" ? "err" : ""}">${esc(d.state)}</span>` : ""}${p.worker ? `<span class="chip label-medium">Worker ${esc(p.worker)}</span>` : ""}</div></article>`;
    })
    .join("");
  const inv = reg.inventory.filter((i) => !i.deployed);
  const body = `<h1 class="display-small">Déployer le monorepo</h1><p class="lead">Chaque commit sur <code>main</code> qui touche un projet est construit en CI, publié sur une URL de preview <code>&lt;projet&gt;-&lt;sha&gt;.aphrody.app</code>, puis promu en production. Les déploiements sont immuables : un rollback ne fait que déplacer le pointeur de production. Construit sur Cloudflare Workers et R2, sans dépendance à un hébergeur tiers.</p><p><a class="btn-filled" href="/dashboard">Ouvrir le tableau de bord</a> <a class="btn-text" href="/labs">Voir les labs</a></p><h2 class="headline-small">Projets déployés par aphrody.app</h2><div class="grid">${cards || '<p class="body-medium">Aucun projet enregistré.</p>'}</div><h2 class="headline-small">Autres unités du monorepo</h2><ul class="list">${inv.map((i) => `<li><span class="grow"><span class="title-medium">${esc(i.name)}</span><p class="body-medium">${esc(i.description || i.path)}</p></span><span class="chip label-medium">${esc(i.kind)}</span><code>${esc(i.path)}</code></li>`).join("")}</ul><p class="body-medium">Inventaire généré au commit <code>${esc(reg.commit.slice(0, 7))}</code> le ${ago(reg.generatedAt)}.</p>`;
  return layout(
    reg,
    "aphrody.app, plateforme de déploiement d'Aphrody",
    "home",
    body,
    "Previews par commit, production, rollback et journaux des projets du monorepo Aphrody.",
  );
}

export function labs(reg: Registry): string {
  const card = (c: LabCard) =>
    `<article class="card-outlined"><a class="title-medium" href="${esc(c.url)}">${esc(c.name)}</a><p class="body-medium">${esc(c.description)}</p>${c.metric ? `<p class="body-medium">Métrique : ${esc(c.metric)}</p>` : ""}<div class="chips">${c.language ? `<span class="chip label-medium">${esc(c.language)}</span>` : ""}${c.pushedAt ? `<span class="chip label-medium">mis à jour ${esc(c.pushedAt.slice(0, 10))}</span>` : ""}${c.homepage ? `<a class="chip label-medium" href="${esc(c.homepage)}">${esc(c.homepage.replace(/^https?:\/\//, ""))}</a>` : ""}</div></article>`;
  const bets = reg.labs.filter((c) => c.source === "alphabet");
  const repos = reg.labs.filter((c) => c.source === "github");
  const body = `<h1 class="display-small">aphrody-labs</h1><p class="lead">Les projets expérimentaux d'Aphrody. Les paris viennent de <a href="https://github.com/aphrody-labs/src/blob/main/docs/ALPHABET.md">docs/ALPHABET.md</a> ; les dépôts sont ceux de l'organisation <a href="https://github.com/aphrody-labs">github.com/aphrody-labs</a> qui ne sont ni des forks ni archivés, avec leur description GitHub.</p><h2 class="headline-small">Paris du monorepo</h2><div class="grid">${bets.map(card).join("")}</div><h2 class="headline-small">Dépôts</h2><div class="grid">${repos.map(card).join("")}</div><p class="body-medium">Liste générée au commit <code>${esc(reg.commit.slice(0, 7))}</code> le ${ago(reg.generatedAt)}.</p>`;
  return layout(
    reg,
    "Labs, aphrody.app",
    "labs",
    body,
    "Projets expérimentaux de l'organisation aphrody-labs.",
  );
}

export function dashboard(
  reg: Registry,
  views: ProjectView[],
  who: string,
): string {
  const rows = views
    .map(
      ({ project: p, state: s, latest: d }) =>
        `<li><span class="grow"><a class="title-medium" href="/dashboard/${esc(p.name)}">${esc(p.name)}</a><p class="body-medium">${p.domains.map((x) => `<a href="https://${esc(x)}">${esc(x)}</a>`).join(", ") || "aucun domaine"}</p></span><span class="body-medium">production <code>${esc(s?.production?.slice(0, 7) ?? "-")}</code></span><span class="body-medium">dernier <code>${esc(d?.sha.slice(0, 7) ?? "-")}</code> ${d ? `<span class="chip label-medium ${d.state === "ready" ? "ok" : d.state === "error" ? "err" : ""}">${esc(d.state)}</span>` : ""}</span></li>`,
    )
    .join("");
  const body = `<h1 class="display-small">Tableau de bord</h1><p class="lead">Connecté via Cloudflare Access : ${esc(who)}.</p><ul class="list">${rows}</ul>`;
  return layout(reg, "Tableau de bord, aphrody.app", "dashboard", body);
}

export function projectPage(
  reg: Registry,
  p: Project,
  s: ProjectState | null,
  deps: Deployment[],
): string {
  const prod = s?.production;
  const items = deps
    .map((d) => {
      const live = d.sha === prod;
      return `<li><span class="grow"><a class="title-medium" href="${esc(previewUrl(p.name, d.sha))}"><code>${esc(d.sha.slice(0, 7))}</code></a> ${live ? '<span class="chip label-medium ok">production</span>' : ""}<p class="body-medium">${esc(d.message)} (${esc(d.branch)}, ${ago(d.readyAt ?? d.createdAt)}${d.files ? `, ${d.files} fichiers, ${Math.round((d.bytes ?? 0) / 1024)} Kio` : ""})</p></span><span class="chip label-medium ${d.state === "ready" ? "ok" : d.state === "error" ? "err" : ""}">${esc(d.state)}</span><a class="btn-text" href="/dashboard/${esc(p.name)}/${esc(d.sha)}/log">Journal</a>${d.run ? `<a class="btn-text" href="${esc(d.run)}">CI</a>` : ""}${!live && d.state === "ready" ? `<form method="post" action="/dashboard/${esc(p.name)}/promote"><input type="hidden" name="sha" value="${esc(d.sha)}"><button class="btn-tonal" type="submit">${prod && deps.findIndex((x) => x.sha === prod) < deps.indexOf(d) ? "Rollback ici" : "Promouvoir"}</button></form>` : ""}</li>`;
    })
    .join("");
  const hist = (s?.history ?? [])
    .slice(-10)
    .reverse()
    .map(
      (h) =>
        `<li><span class="grow"><code>${esc(h.sha.slice(0, 7))}</code> ${esc(h.action)} par ${esc(h.by)}</span>${ago(h.at)}</li>`,
    )
    .join("");
  const body = `<h1 class="display-small">${esc(p.name)}</h1><p class="lead"><code>${esc(p.path)}</code>, construit par <code>${esc(p.build)}</code>, sortie <code>${esc(p.out)}</code>${p.worker ? `, servi en production par le Worker <code>${esc(p.worker)}</code>` : ""}.</p><div class="grid"><section class="card-filled"><h2 class="title-medium">Domaines</h2><p class="body-medium">${p.domains.map((x) => `<a href="https://${esc(x)}">${esc(x)}</a>`).join("<br>") || "aucun"}</p></section><section class="card-filled"><h2 class="title-medium">Variables (coffre env-kit)</h2><p class="body-medium">${p.env.length ? p.env.map((x) => `<code>${esc(x)}</code>`).join(" ") : "aucune"}</p></section><section class="card-filled"><h2 class="title-medium">Production</h2><p class="body-medium">${prod ? `<a href="${esc(previewUrl(p.name, prod))}"><code>${esc(prod.slice(0, 7))}</code></a>` : "aucune"}</p></section></div><h2 class="headline-small">Déploiements</h2><ul class="list">${items || "<li>Aucun déploiement.</li>"}</ul><h2 class="headline-small">Historique de production</h2><ul class="list">${hist || "<li>Vide.</li>"}</ul>`;
  return layout(reg, `${p.name}, aphrody.app`, "dashboard", body);
}

export function logPage(
  reg: Registry,
  p: string,
  sha: string,
  log: string,
): string {
  return layout(
    reg,
    `Journal ${p}@${sha.slice(0, 7)}`,
    "dashboard",
    `<h1 class="display-small">Journal de ${esc(p)}@<code>${esc(sha.slice(0, 7))}</code></h1><p><a class="btn-text" href="/dashboard/${esc(p)}">Retour</a></p><pre>${esc(log)}</pre>`,
  );
}
